def solve(data):
    nums = data["nums"]
    target = data["target"]

    # Edge cases: empty array or single element array with target smaller than or equal to the element
    if not nums or target <= nums[0]:
        return 0

    # Edge case: single element array with target larger than the element
    elif target > nums[-1]:
        return len(nums)

    # Binary search to find the insertion point
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid

    # If loop exits without finding target, left will be at the correct position for insertion
    return left

def solve(data):
    nums = data['nums']
    target = data['target']

    # Edge cases: empty list or target is already in the list
    if not nums or target in nums:
        return nums.index(target) if target in nums else len(nums)

    # Brute force approach
    for i in range(len(nums)):
        if nums[i] >= target:
            return i

    # If no element is found, insert at the end
    return len(nums)
